// Stage 6 (guests): outside context for one guest, from public sources only. Nothing here is generated by a model.
import Parser from "rss-parser";
import { db } from "./db-core";
import { searchByPerson } from "./podcastindex";

const WEEK = 7 * 86_400_000;
const PI_MAX = 60;
const UA = "PodcastRadar/0.1 (internal research tool)";

export type Wiki = {
  title: string; description: string | null; extract: string; image: string | null; url: string;
  /** True when the article mentions the guest's company or role, not just the name. */
  confirmed: boolean;
};
export type PodcastAppearance = { feed: string; title: string; date: string; url: string | null };
export type Footprint = { total: number; capped: boolean; last90: number; ownShow: string | null; items: PodcastAppearance[] };
export type Headline = { title: string; source: string | null; date: string | null; url: string };

export type Source<T> = { data: T | null; fetchedAt: string | null; error?: string };
export type GuestEnrichment = { wiki: Source<Wiki | null>; podcasts: Source<Footprint>; news: Source<Headline[]> };

export type GuestBasics = { id: string; name: string; company: string | null; role: string | null };

async function wikipedia(g: GuestBasics): Promise<Wiki | null> {
  const params = new URLSearchParams({
    action: "query", titles: g.name, redirects: "1", format: "json", formatversion: "2",
    prop: "extracts|pageimages|description|pageprops|info", exintro: "1", explaintext: "1", pithumbsize: "320", inprop: "url",
  });
  const res = await fetch(`https://en.wikipedia.org/w/api.php?${params}`, { headers: { "User-Agent": UA } });
  if (!res.ok) throw new Error(`Wikipedia ${res.status}`);
  const page = (await res.json()).query?.pages?.[0];
  if (!page || page.missing || page.pageprops?.disambiguation !== undefined || !page.extract) return null;
  const text = `${page.description ?? ""} ${page.extract}`.toLowerCase();
  const clues = [g.company, g.role].filter(Boolean).flatMap((s) => s!.toLowerCase().split(/[^a-z0-9]+/)).filter((w) => w.length > 3);
  return {
    title: page.title, description: page.description ?? null, extract: String(page.extract).split("\n")[0].slice(0, 700),
    image: page.thumbnail?.source ?? null, url: page.fullurl ?? `https://en.wikipedia.org/wiki/${encodeURIComponent(page.title)}`,
    confirmed: clues.some((w) => text.includes(w)),
  };
}

async function podcasts(g: GuestBasics): Promise<Footprint> {
  const ours = (await db().execute("select name from shows")).rows.map((r) => String(r.name).toLowerCase());
  const all = await searchByPerson(g.name, PI_MAX);
  const items = all
    // Our own shows are already counted on the radar; this section is about everywhere else.
    .filter((i) => !ours.some((s) => i.feed.toLowerCase().includes(s) || s.includes(i.feed.toLowerCase())));
  const cutoff = Date.now() - 90 * 86_400_000;
  const name = g.name.toLowerCase();
  return {
    total: items.length, capped: all.length >= PI_MAX,
    last90: items.filter((i) => Date.parse(i.date) >= cutoff).length,
    ownShow: items.find((i) => i.feed.toLowerCase().includes(name))?.feed ?? null,
    items: items.slice(0, 8),
  };
}

async function news(g: GuestBasics): Promise<Headline[]> {
  const q = `"${g.name}" when:90d`;
  const url = `https://news.google.com/rss/search?${new URLSearchParams({ q, hl: "en-IN", gl: "IN", ceid: "IN:en" })}`;
  const feed = await new Parser({ timeout: 15_000, headers: { "User-Agent": UA } }).parseURL(url);
  return feed.items
    .map((it) => {
      // Google News titles end in " - Publisher".
      const raw = it.title ?? "", cut = raw.lastIndexOf(" - ");
      return {
        title: cut > 0 ? raw.slice(0, cut) : raw, source: cut > 0 ? raw.slice(cut + 3) : null,
        date: it.isoDate ?? null, url: it.link ?? "",
      };
    })
    .sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""))
    .slice(0, 6);
}

const FETCHERS = { wikipedia, podcastindex: podcasts, news } as const;
type Key = keyof typeof FETCHERS;

/** Cached per guest and source for a week; stale or missing sources are fetched in parallel. A failing source never breaks the others. */
export async function enrichGuest(g: GuestBasics, opts: { force?: boolean } = {}): Promise<GuestEnrichment> {
  const c = db();
  const cached = new Map((await c.execute({
    sql: `select source, payload, fetched_at from enrichments where entity_type = 'guest' and entity_id = ?
          order by fetched_at`,
    args: [g.id],
  })).rows.map((r) => [String(r.source), { payload: String(r.payload), at: String(r.fetched_at) }]));

  const load = async <K extends Key>(key: K): Promise<Source<Awaited<ReturnType<(typeof FETCHERS)[K]>>>> => {
    const hit = cached.get(key);
    if (hit && !opts.force && Date.now() - Date.parse(hit.at) < WEEK) return { data: JSON.parse(hit.payload), fetchedAt: hit.at };
    try {
      const data = await FETCHERS[key](g);
      const at = new Date().toISOString();
      await c.batch([
        { sql: "delete from enrichments where entity_type = 'guest' and entity_id = ? and source = ?", args: [g.id, key] },
        { sql: "insert into enrichments (entity_type, entity_id, source, payload, fetched_at) values ('guest', ?, ?, ?, ?)", args: [g.id, key, JSON.stringify(data), at] },
      ], "write");
      return { data: data as never, fetchedAt: at };
    } catch (e) {
      // Fall back to an old copy rather than showing nothing.
      return { data: hit ? JSON.parse(hit.payload) : null, fetchedAt: hit?.at ?? null, error: (e as Error).message };
    }
  };

  const [wiki, pods, headlines] = await Promise.all([load("wikipedia"), load("podcastindex"), load("news")]);
  return { wiki, podcasts: pods, news: headlines };
}
